settings.markdownCss:
.cz-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: 'Roboto', sans-serif;
  height: 100%;
}
.cz-title {
  font-size: 14px;
  color: #888;
  font-weight: 500;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.cz-icon {
  width: 56px;
  height: 56px;
  color: #1976d2;
  margin-bottom: 8px;
}
.cz-update {
  font-size: 13px;
  color: #888;
  margin-bottom: 16px;
}
.cz-zone {
  font-size: 32px;
  font-weight: 600;
  color: #2e7d32;
  text-transform: capitalize;
}
.cz-mac {
  font-size: 13px;
  font-weight: 500;
  color: #888;
  text-transform: none;
  font-family: 'Roboto Mono', monospace;
  margin-top: 6px;
  text-align: center;
}

.td-card {
  padding: 16px;
  font-family: 'Roboto', sans-serif;
  height: 100%;
}
.td-title {
  font-size: 16px;
  font-weight: 600;
  color: #333;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid #eee;
}
.td-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 4px;
  border-bottom: 1px solid #f5f5f5;
  font-size: 14px;
}
.td-row:last-child {
  border-bottom: none;
}
.td-label {
  color: #777;
  font-weight: 500;
}
.td-value {
  color: #2e7d32;
  font-weight: 600;
  font-family: 'Roboto Mono', monospace;
}

.fp-container {
  padding: 16px;
  font-family: 'Roboto', sans-serif;
  height: 100%;
}
.fp-title {
  font-size: 16px;
  font-weight: 600;
  color: #333;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid #eee;
}
.fp-zone {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  margin-bottom: 10px;
  border-radius: 8px;
  background: #fafafa;
  border: 1px solid #e0e0e0;
}
.fp-room_1-active-room_1,
.fp-room_3-active-room_3,
.fp-room_2-active-room_2,
.fp-room_4-active-room_4 {
  background: #e3f2fd !important;
  border-color: #1976d2 !important;
  box-shadow: 0 2px 8px rgba(25, 118, 210, 0.15) !important;
}
.fp-zone-name {
  font-size: 15px;
  font-weight: 600;
  color: #222;
}
.fp-zone-meta {
  font-size: 12px;
  color: #888;
  font-family: 'Roboto Mono', monospace;
  display: block;
  margin-top: 4px;
}
.fp-here-badge {
  display: none;
  background: #1976d2;
  color: #fff;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}
.fp-room_1-active-room_1 .fp-here-badge,
.fp-room_3-active-room_3 .fp-here-badge,
.fp-room_2-active-room_2 .fp-here-badge,
.fp-room_4-active-room_4 .fp-here-badge {
  display: inline-block;
}

